excels.excel:

EXPORT WITH SHEET="销售订单执行跟踪", HEADER=true,
    MAPPING={"a":"订单号","b":"客户名称","c":"订单金额","d":"已发货金额","e":"未发货金额","f":"执行率","g":"订单状态"},
    FORMAT={"c":"#,##0.00","d":"#,##0.00","e":"#,##0.00","f":"0.00%"},
    FORMULAS={
        E2:'C2-D2',F2:'D2/C2',
        E3:'C3-D3',F3:'D3/C3',
        E4:'C4-D4',F4:'D4/C4',
        E5:'C5-D5',F5:'D5/C5',
        E6:'C6-D6',F6:'D6/C6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'C7-D7',F7:'D7/C7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F6:{color:red,bold:true}
    }
